INSERT INTO `announcements` VALUES (1,1,2,'Welcome to AI Genesis 2026!','We are thrilled to welcome all participants! Team formation is now open. Make sure to read the problem statements and review guidelines in the dashboard.',1,'2026-10-05 11:04:57'),(2,1,2,'Mentorship Hours & Cloud Credits Released','AWS and Google Cloud credits have been emailed to all confirmed team leaders. Join the mentorship channel for architecture reviews this Friday.',0,'2026-10-05 11:04:57'),(3,2,3,'Testnet Faucets & Smart Contract Templates','Sepolia and Polygon testnet faucets are active. Starter contracts with audited ERC-20 and ERC-4337 account abstraction are linked in the resources page.',1,'2026-10-05 11:04:57'),(4,3,2,'Medical Datasets & HIPAA Sandbox API Available','The anonymized ICU vital signs and synthetic ECG datasets are now accessible for all registered teams. Please comply with our data usage ethics pledge.',1,'2026-10-05 11:04:57'),(5,4,4,'CTF Qualification Round Starts Tomorrow at 10 AM','All registered security teams must check in 15 minutes prior to flag release. Network isolation rules and target VPN credentials have been published.',1,'2026-10-05 11:04:57'),(6,5,3,'Final Evaluation Results & Winner Ceremony','Congratulations to all teams who submitted! Top 3 prototypes for the GreenTech challenge have been selected. Awards ceremony will commence at 5:00 PM.',0,'2026-10-05 11:04:57'),(7,7,2,'Project Submission Review Complete','All early bird submissions have been evaluated. Check dashboard for feedback.',1,'2026-10-05 11:18:01'),(9,9,25,'Weekly Office Hours','Drop in on Discord tomorrow at 4 PM.',0,'2026-10-05 11:34:40'),(10,10,2,'Project Submission Review Complete','All early bird submissions have been evaluated. Check dashboard for feedback.',1,'2026-10-05 11:34:47'),(11,11,2,'Project Submission Review Complete','All early bird submissions have been evaluated. Check dashboard for feedback.',1,'2026-10-05 11:46:43'),(13,12,34,'Weekly Office Hours','Drop in on Discord tomorrow at 4 PM.',0,'2026-10-05 11:46:50'),(17,15,2,'Project Submission Review Complete','All early bird submissions have been evaluated. Check dashboard for feedback.',1,'2026-10-05 12:55:53'),(19,16,50,'Weekly Office Hours','Drop in on Discord tomorrow at 4 PM.',0,'2026-10-05 12:56:00'),(22,23,2,'Project Submission Review Complete','All early bird submissions have been evaluated. Check dashboard for feedback.',1,'2026-10-05 13:08:24'),(24,24,61,'Weekly Office Hours','Drop in on Discord tomorrow at 4 PM.',0,'2026-10-05 13:09:03'),(26,25,66,'Weekly Office Hours','Drop in on Discord tomorrow at 4 PM.',0,'2026-10-05 13:09:35'),(27,26,2,'Project Submission Review Complete','All early bird submissions have been evaluated. Check dashboard for feedback.',1,'2026-10-05 14:07:49'),(30,28,75,'Weekly Office Hours','Drop in on Discord tomorrow at 4 PM.',0,'2026-10-05 14:08:01'),(31,32,2,'Project Submission Review Complete','All early bird submissions have been evaluated. Check dashboard for feedback.',1,'2026-10-05 14:31:49'),(33,33,82,'Weekly Office Hours','Drop in on Discord tomorrow at 4 PM.',0,'2026-10-05 14:31:58'),(35,36,2,'Project Submission Review Complete','All early bird submissions have been evaluated. Check dashboard for feedback.',1,'2026-10-05 14:34:04'),(37,37,91,'Weekly Office Hours','Drop in on Discord tomorrow at 4 PM.',0,'2026-10-05 14:34:20'),(39,40,2,'Project Submission Review Complete','All early bird submissions have been evaluated. Check dashboard for feedback.',1,'2026-10-05 15:17:40'),(41,41,100,'Weekly Office Hours','Drop in on Discord tomorrow at 4 PM.',0,'2026-10-05 15:17:47');
