INSERT INTO `hackathons` VALUES (1,2,'AI Genesis Hackathon 2026','Build next-generation generative AI and intelligent agent applications solving real-world challenges.','https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&w=800&q=80','2026-11-15 09:00:00','2026-11-17 18:00:00','2026-11-10 23:59:59',2,4,'UPCOMING','Hybrid - MIT Campus & Online','2026-10-05 11:04:57','2026-10-05 11:04:57'),(2,3,'Web3 & FinTech Revolution','Decentralized finance, smart contract security, cross-border payments, and Web3 identity protocols.','https://images.unsplash.com/photo-1639762681485-074b7f938ba0?auto=format&fit=crop&w=800&q=80','2026-12-01 10:00:00','2026-12-03 20:00:00','2026-11-25 23:59:59',1,3,'UPCOMING','Online (Discord & GitHub)','2026-10-05 11:04:57','2026-10-05 11:04:57'),(3,2,'Smart Health & BioTech Sprint','Leverage predictive AI, wearable sensors, and telemedicine to transform preventive digital healthcare.','https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?auto=format&fit=crop&w=800&q=80','2026-10-01 09:00:00','2026-10-10 18:00:00','2026-09-28 23:59:59',2,4,'ONGOING','IIT Bombay Research Labs','2026-10-05 11:04:57','2026-10-05 11:04:57'),(4,4,'CyberShield National Hackathon','Offensive and defensive security tooling, zero-trust architectures, and automated vulnerability detection.','https://images.unsplash.com/photo-1550751827-4bd374c3f58b?auto=format&fit=crop&w=800&q=80','2026-10-03 08:00:00','2026-10-08 22:00:00','2026-09-30 23:59:59',1,4,'ONGOING','Online','2026-10-05 11:04:57','2026-10-05 11:04:57'),(5,3,'GreenTech Clean Energy Challenge','Develop IoT and AI solutions for smart grids, carbon tracking, and renewable energy distribution.','https://images.unsplash.com/photo-1497435334941-8c899ee9e8e9?auto=format&fit=crop&w=800&q=80','2026-08-10 09:00:00','2026-08-12 18:00:00','2026-08-05 23:59:59',2,5,'COMPLETED','Bengaluru Innovation Center','2026-10-05 11:04:57','2026-10-05 11:04:57'),(6,4,'EdTech Odyssey 2026','Reinvent digital learning, accessibility tools, and interactive STEM education platforms.','https://images.unsplash.com/photo-1503676260728-1c00da094a0b?auto=format&fit=crop&w=800&q=80','2026-12-15 09:00:00','2026-12-17 18:00:00','2026-12-10 23:59:59',1,3,'UPCOMING','Online','2026-10-05 11:04:57','2026-10-05 11:04:57'),(7,2,'Cloud Native & DevOps Sprint 2026','Build automated Kubernetes pipelines and microservices tooling.',NULL,'2026-12-20 09:00:00','2026-12-22 18:00:00','2026-12-18 23:59:59',1,3,'UPCOMING','Online','2026-10-05 11:18:00','2026-10-05 11:18:00'),(8,20,'Quantum Computing & Algorithms Hackathon 2026','Admin verified and updated description.',NULL,'2026-12-05 09:00:00','2026-12-07 18:00:00','2026-11-30 23:59:59',1,3,'UPCOMING','Online','2026-10-05 11:34:19','2026-10-05 11:34:19'),(9,25,'Quantum Computing & Algorithms Hackathon 2026','Admin verified and updated description.',NULL,'2026-12-05 09:00:00','2026-12-07 18:00:00','2026-11-30 23:59:59',1,3,'UPCOMING','Online','2026-10-05 11:34:39','2026-10-05 11:34:39'),(10,2,'Cloud Native & DevOps Sprint 2026','Build automated Kubernetes pipelines and microservices tooling.',NULL,'2026-12-20 09:00:00','2026-12-22 18:00:00','2026-12-18 23:59:59',1,3,'UPCOMING','Online','2026-10-05 11:34:47','2026-10-05 11:34:47'),(11,2,'Cloud Native & DevOps Sprint 2026','Build automated Kubernetes pipelines and microservices tooling.',NULL,'2026-12-20 09:00:00','2026-12-22 18:00:00','2026-12-18 23:59:59',1,3,'UPCOMING','Online','2026-10-05 11:46:42','2026-10-05 11:46:42'),(12,34,'Quantum Computing & Algorithms Hackathon 2026','Admin verified and updated description.',NULL,'2026-12-05 09:00:00','2026-12-07 18:00:00','2026-11-30 23:59:59',1,3,'UPCOMING','Online','2026-10-05 11:46:49','2026-10-05 11:46:50'),(13,2,'Admin Verified CleanTech Sprint 1791204860111','Design and prototype software solutions targeting carbon capture tracking and renewable grid balancing.',NULL,'2026-11-15 09:00:00','2026-11-17 18:00:00','2026-11-10 23:59:59',2,4,'UPCOMING','Hybrid - MIT Campus','2026-10-05 12:54:20','2026-10-05 12:54:20'),(14,2,'Admin Verified CleanTech Sprint 1791204911867','Design and prototype software solutions targeting carbon capture tracking and renewable grid balancing.',NULL,'2026-11-15 03:30:00','2026-11-17 12:30:00','2026-11-10 18:29:59',2,4,'UPCOMING','Hybrid - MIT Campus','2026-10-05 12:55:12','2026-10-05 12:55:12'),(15,2,'Cloud Native & DevOps Sprint 2026','Build automated Kubernetes pipelines and microservices tooling.',NULL,'2026-12-20 03:30:00','2026-12-22 12:30:00','2026-12-18 18:29:59',1,3,'UPCOMING','Online','2026-10-05 12:55:53','2026-10-05 12:55:53'),(16,50,'Quantum Computing & Algorithms Hackathon 2026','Admin verified and updated description.',NULL,'2026-12-05 03:30:00','2026-12-07 12:30:00','2026-11-30 18:29:59',1,3,'UPCOMING','Online','2026-10-05 12:55:59','2026-10-05 12:56:00'),(17,2,'Admin Verified CleanTech Sprint 1791204979831','Design and prototype software solutions targeting carbon capture tracking and renewable grid balancing.',NULL,'2026-11-15 03:30:00','2026-11-17 12:30:00','2026-11-10 18:29:59',2,4,'UPCOMING','Hybrid - MIT Campus','2026-10-05 12:56:20','2026-10-05 12:56:20'),(18,3,'Q-HACK INDIA 2026','National-level quantum computing hackathon hosted by QuantumRIT in collaboration with industry partners. Features 4 specialized tracks: Quantum Biotech & Chemistry, Quantum Security & Cryptography, Quantum AI & Software, and Open Quantum Innovation. Finalists compete in a 2-day in-person hackathon in Bengaluru.\n\n[Source: Devfolio | https://devfolio.co/hackathons/q-hack-india-2026]','https://images.unsplash.com/photo-1635070041078-e363dbe005cb?auto=format&fit=crop&w=800&q=80','2026-10-30 09:00:00','2026-10-31 18:00:00','2026-10-20 23:59:59',3,4,'UPCOMING','Ramaiah Institute of Technology, Bengaluru','2026-10-05 13:05:46','2026-10-05 13:05:46'),(19,2,'HackShift 2026 – IIIT Delhi','A flagship two-stage hackathon organized by the Entrepreneurship Cell at IIIT Delhi under the theme \"Cmd, Shift, Create\". Round 1 requires an online proposal slide-deck submission on campus engagement or event tooling; shortlisted teams qualify for the 24-hour on-campus hackathon at IIIT Delhi.\n\n[Source: Unstop | https://unstop.com/hackathons/hackshift-iiit-delhi]','https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?auto=format&fit=crop&w=800&q=80','2026-10-17 09:00:00','2026-10-18 18:00:00','2026-10-15 23:59:59',1,4,'UPCOMING','IIIT Delhi Campus, New Delhi','2026-10-05 13:05:46','2026-10-05 13:05:46'),(20,3,'ETHGlobal Mumbai 2026','Leading Ethereum ecosystem hackathon bringing global developers to Mumbai. 36 hours of non-stop building focusing on decentralized finance, smart contract security, zero-knowledge proofs, and cross-chain interoperability with mentorship from core Ethereum protocol researchers.\n\n[Source: ETHGlobal | https://ethglobal.com/events/mumbai]','https://images.unsplash.com/photo-1639762681485-074b7f938ba0?auto=format&fit=crop&w=800&q=80','2026-11-06 10:00:00','2026-11-08 17:00:00','2026-11-01 23:59:59',1,5,'UPCOMING','Jio World Convention Centre, Mumbai','2026-10-05 13:05:46','2026-10-05 13:05:46'),(21,4,'Vihaan X 2026 – IEEE DTU','Annual flagship national hackathon hosted by IEEE Delhi Technological University (DTU). Features 24-hour intense sprints in Artificial Intelligence, HealthTech, Smart City IoT, and Sustainable Tech with tracks judged by leading engineers and faculty.\n\n[Source: Unstop | https://unstop.com/hackathons/vihaan-x-dtu]','https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?auto=format&fit=crop&w=800&q=80','2026-11-14 09:00:00','2026-11-15 18:00:00','2026-11-09 23:59:59',1,4,'UPCOMING','Delhi Technological University (DTU), New Delhi','2026-10-05 13:05:46','2026-10-05 13:05:46'),(22,2,'Admin Verified CleanTech Sprint 1791205694175','Design and prototype software solutions targeting carbon capture tracking and renewable grid balancing.',NULL,'2026-11-15 03:30:00','2026-11-17 12:30:00','2026-11-10 18