INSERT INTO `project_ideas` VALUES (1,1,5,1,'NeuroScribe – Automated Clinical Notes via Whisper & LLMs','NeuroScribe uses fine-tuned speech recognition and LLMs to transcribe doctor-patient conversations into structured EHR notes in real time, reducing physician documentation burnout by 70%.','AI/ML','Python, PyTorch, Whisper, React, FastAPI','https://neuroscribe-demo.vercel.app','https://github.com/aaravpatel/neuroscribe',1,'ACCEPTED','2026-10-05 11:04:57','2026-10-05 11:04:57'),(2,2,8,2,'DecentraPay – Cross-Border Micropayments on Layer-2','A high-throughput, low-fee remittance protocol utilizing zero-knowledge rollups and decentralized liquidity pools for instant cross-border worker remittances.','FinTech','Solidity, Polygon zkEVM, Next.js, Node.js','https://decentrapay.finance','https://github.com/ananyasen/decentrapay',1,'UNDER_REVIEW','2026-10-05 11:04:57','2026-10-05 11:04:57'),(3,3,6,3,'CardioVision – Real-Time Arrhythmia Detection with Edge IoT','An ultra-low-power wearable ECG patch paired with on-device quantized neural networks for real-time arrhythmia prediction and automated emergency ambulance alerts.','HealthTech','TensorFlow Lite, C++, Flutter, Raspberry Pi Pico',NULL,'https://github.com/sneha-reddy/cardiovision',0,'SUBMITTED','2026-10-05 11:04:57','2026-10-05 11:04:57'),(4,4,13,NULL,'PhishGuard – Zero-Day Email Threat Engine','A behavioral analysis engine that detects sophisticated spear-phishing and business email compromise by evaluating syntactic intent and domain entropy.','CyberSecurity','Python, Rust, Scikit-learn, Docker','https://phishguard.security.io','https://github.com/kabirdas/phishguard',1,'SUBMITTED','2026-10-05 11:04:57','2026-10-05 11:04:57'),(5,5,14,NULL,'SolarSync – Peer-to-Peer Solar Surplus Energy Exchange','A localized energy trading platform that allows households with solar rooftop panels to trade excess kilowatt-hours with neighbors over an automated smart microgrid.','CleanTech & Energy','React, Express, ESP32, MQTT, MySQL','https://solarsync.energy','https://github.com/tanvihegde/solarsync',1,'ACCEPTED','2026-10-05 11:04:57','2026-10-05 11:04:57'),(6,6,14,NULL,'CampusLearn – Collaborative Peer Learning & Knowledge Graph','An adaptive study platform that clusters lecture concepts into interactive knowledge graphs and pairs students for targeted peer tutoring based on syllabus weaknesses.','EdTech','React, Node.js, WebSockets, Neo4j, MySQL',NULL,'https://github.com/tanvihegde/campuslearn',0,'UNDER_REVIEW','2026-10-05 11:04:57','2026-10-05 11:04:57'),(7,3,9,NULL,'BioSentinel – Non-Invasive Early Sepsis Warning Monitor','Continuous vital signs monitoring and multivariate regression alerting clinical ICU teams 6 hours prior to overt septic shock manifestation.','HealthTech','Python, XGBoost, Docker, Flask',NULL,'https://github.com/karanjoshi/biosentinel',1,'REJECTED','2026-10-05 11:04:57','2026-10-05 11:04:57'),(9,7,17,5,'KubeGuard – Automated Cluster Security Scanner','An automated Kubernetes admission controller evaluating CIS benchmarks and RBAC misconfigurations.','Cloud & DevOps','Go, Kubernetes, React, Helm','https://kubeguard.io','https://github.com/cloudvanguard/kubeguard',1,'ACCEPTED','2026-10-05 11:18:00','2026-10-05 11:18:01'),(10,9,24,7,'Q-Shield – Advanced Post-Quantum Cryptography Engine','Implementation of lattice-based CRYSTALS-Kyber for secure real-time microservice communication.','AI/ML','Python, Qiskit, C++, WebAssembly','https://q-shield.network','https://github.com/quantumleap/q-shield',1,'ACCEPTED','2026-10-05 11:34:39','2026-10-05 11:34:39'),(11,10,29,8,'KubeGuard – Automated Cluster Security Scanner','An automated Kubernetes admission controller evaluating CIS benchmarks and RBAC misconfigurations.','Cloud & DevOps','Go, Kubernetes, React, Helm','https://kubeguard.io','https://github.com/cloudvanguard/kubeguard',1,'ACCEPTED','2026-10-05 11:34:47','2026-10-05 11:34:47'),(12,11,31,9,'KubeGuard – Automated Cluster Security Scanner','An automated Kubernetes admission controller evaluating CIS benchmarks and RBAC misconfigurations.','Cloud & DevOps','Go, Kubernetes, React, Helm','https://kubeguard.io','https://github.com/cloudvanguard/kubeguard',1,'ACCEPTED','2026-10-05 11:46:43','2026-10-05 11:46:43'),(13,12,33,10,'Q-Shield – Advanced Post-Quantum Cryptography Engine','Implementation of lattice-based CRYSTALS-Kyber for secure real-time microservice communication.','AI/ML','Python, Qiskit, C++, WebAssembly','https://q-shield.network','https://github.com/quantumleap/q-shield',1,'ACCEPTED','2026-10-05 11:46:50','2026-10-05 11:46:50'),(14,1,41,11,'Decentralized AI Grid 1791201457727','A distributed edge computing architecture for local neural inferencing during network blackouts.','AI/ML','React, Node.js, Express, MySQL 8.4, Docker',NULL,NULL,1,'ACCEPTED','2026-10-05 11:57:38','2026-10-05 11:57:38'),(15,1,43,12,'Decentralized AI Grid 1791204860111','A distributed edge computing architecture for local neural inferencing during network blackouts.','AI/ML','React, Node.js, Express, MySQL 8.4, Docker',NULL,NULL,1,'ACCEPTED','2026-10-05 12:54:20','2026-10-05 12:54:20'),(16,1,45,14,'Decentralized AI Grid 1791204911867','A distributed edge computing architecture for local neural inferencing during network blackouts.','AI/ML','React, Node.js, Express, MySQL 8.4, Docker',NULL,NULL,1,'ACCEPTED','2026-10-05 12:55:12','2026-10-05 12:55:12'),(17,15,47,15,'KubeGuard – Automated Cluster Security Scanner','An automated Kubernetes admission controller evaluating CIS benchmarks and RBAC misconfigurations.','Cloud & DevOps','Go, Kubernetes, React, Helm','https://kubeguard.io','https://github.com/cloudvanguard/kubeguard',1,'ACCEPTED','2026-10-05 12:55:53','2026-10-05 12:55:53'),(18,16,49,16,'Q-Shield – Advanced Post-Quantum Cryptography Engine','Implementation of lattice-based CRYSTALS-Kyber for secure real-time microservice communication.','AI/ML','Python, Qiskit, C++, WebAssembly','https://q-shield.network','https://github.com/quantumleap/q-shield',